#include <stdio.h>
#include <string.h>
#include "app.h"
static void flushline(void){int c;while((c=getchar())!='\n'&&c!=EOF){}}
static int line(const char*p,char*b,size_t n){printf("%s",p);if(!fgets(b,n,stdin))return 0;char*q=strchr(b,'\n');if(q)*q=0;else flushline();return b[0]!=0;}
static int integer(const char*p,int*out){char b[64],x; if(!line(p,b,sizeof b))return 0;return sscanf(b,"%d %c",out,&x)==1;}
static int realnum(const char*p,float*out){char b[64],x;if(!line(p,b,sizeof b))return 0;return sscanf(b,"%f %c",out,&x)==1;}
void studentMenu(void){for(;;){int c;if(!integer("\nSTUDENT MANAGEMENT\n1 Add  2 View  3 Search  4 Back\nChoice: ",&c))continue;if(c==4)return;if(c==1){Student s={0};generateStudentId(s.studentId);printf("Generated ID: %s\n",s.studentId);if(!line("Roll: ",s.rollNumber,sizeof s.rollNumber)||rollExists(s.rollNumber)||!line("Name: ",s.name,sizeof s.name)||!line("Branch: ",s.branch,sizeof s.branch)){puts("Invalid/duplicate data.");continue;}puts(saveStudent(&s)?"Student saved.":"Save failed.");}else if(c==2){FILE*f=fopen(STUDENT_FILE,"rb");Student s;puts("ID        ROLL        NAME                         BRANCH");if(!f){puts("No students.");continue;}while(fread(&s,sizeof s,1,f)==1)printf("%-9s %-11s %-28s %s\n",s.studentId,s.rollNumber,s.name,s.branch);fclose(f);}else if(c==3){char id[MAX_ID_LENGTH];Student s;if(line("Student ID: ",id,sizeof id)&&findStudentById(id,&s))printf("%s | %s | %s | %s\n",s.studentId,s.rollNumber,s.name,s.branch);else puts("Student not found.");}}
}
void subjectMenu(void){for(;;){int c;if(!integer("\nSUBJECT MANAGEMENT\n1 Add  2 View  3 Back\nChoice: ",&c))continue;if(c==3)return;if(c==1){Subject s={0};if(!line("Code: ",s.subjectCode,sizeof s.subjectCode)||findSubject(s.subjectCode,NULL)||!line("Name: ",s.subjectName,sizeof s.subjectName)||!line("Comparison group: ",s.comparisonGroup,sizeof s.comparisonGroup)||!integer("Semester: ",&s.semester)||s.semester<1||s.semester>MAX_SEMESTERS||!realnum("Maximum marks: ",&s.maximumMarks)||s.maximumMarks<=0||!realnum("Passing marks: ",&s.passingMarks)||s.passingMarks<0||s.passingMarks>s.maximumMarks){puts("Invalid/duplicate subject data.");continue;}puts(saveSubject(&s)?"Subject saved.":"Save failed.");}else if(c==2){FILE*f=fopen(SUBJECT_FILE,"rb");Subject s;if(!f){puts("No subjects.");continue;}while(fread(&s,sizeof s,1,f)==1)printf("%s | %s | Sem %d | %.1f max | %.1f pass\n",s.subjectCode,s.subjectName,s.semester,s.maximumMarks,s.passingMarks);fclose(f);}}
}
static int markExists(const char*id,const char*code,int sem){FILE*f=fopen(MARKS_FILE,"rb");if(!f)return 0;MarkRecord m;while(fread(&m,sizeof m,1,f)==1)if(!strcmp(m.studentId,id)&&!strcmp(m.subjectCode,code)&&m.semester==sem){fclose(f);return 1;}fclose(f);return 0;}
void marksMenu(void){for(;;){int c;if(!integer("\nMARKS MANAGEMENT\n1 Enter marks  2 View marks  3 Back\nChoice: ",&c))continue;if(c==3)return;if(c==1){MarkRecord m={0};Subject s;if(!line("Student ID: ",m.studentId,sizeof m.studentId)||!studentIdExists(m.studentId)||!integer("Semester: ",&m.semester)||!line("Subject code: ",m.subjectCode,sizeof m.subjectCode)||!findSubject(m.subjectCode,&s)||s.semester!=m.semester||markExists(m.studentId,m.subjectCode,m.semester)||!realnum("Marks: ",&m.marksObtained)||m.marksObtained<0||m.marksObtained>s.maximumMarks){puts("Invalid, duplicate, or inconsistent marks record.");continue;}puts(saveMark(&m)?"Marks saved.":"Save failed.");}else if(c==2){char id[MAX_ID_LENGTH];int sem;if(!line("Student ID: ",id,sizeof id)||!integer("Semester: ",&sem))continue;FILE*f=fopen(MARKS_FILE,"rb");MarkRecord m;Subject s;if(!f){puts("No marks.");continue;}while(fread(&m,sizeof m,1,f)==1)if(!strcmp(m.studentId,id)&&m.semester==sem&&findSubject(m.subjectCode,&s))printf("%-10s %-25s %.2f/%.2f\n",s.subjectCode,s.subjectName,m.marksObtained,s.maximumMarks);fclose(f);}}
}
void calculateResult(void){char id[MAX_ID_LENGTH];int sem;if(!line("Student ID: ",id,sizeof id)||!studentIdExists(id)||!integer("Semester: ",&sem)){puts("Invalid student/semester.");return;}FILE*sf=fopen(SUBJECT_FILE,"rb");if(!sf){puts("No subjects.");return;}Subject s;int required=0,found=0,failed=0;float got=0,max=0;while(fread(&s,sizeof s,1,sf)==1)if(s.semester==sem){required++;FILE*mf=fopen(MARKS_FILE,"rb");MarkRecord m;int ok=0;if(mf){while(fread(&m,sizeof m,1,mf)==1)if(!strcmp(m.studentId,id)&&!strcmp(m.subjectCode,s.subjectCode)&&m.semester==sem){ok=1;found++;got+=m.marksObtained;max+=s.maximumMarks;if(m.marksObtained<s.passingMarks)failed=1;break;}fclose(mf);}if(!ok)printf("Missing: %s - %s\n",s.subjectCode,s.subjectName);}fclose(sf);if(!required||found!=required){printf("Incomplete record (%d/%d subjects). Result not finalized.\n",found,required);return;}SemesterResult r={0};strcpy(r.studentId,id);r.semester=sem;r.totalMarksObtained=got;r.totalMaximumMarks=max;r.percentage=percentage(got,max);getGrade(r.percentage,r.overallGrade);r.passed=!failed;if(upsertResult(&r))printf("Result: %.2f/%.2f | %.2f%% | %s | %s\n",got,max,r.percentage,r.overallGrade,r.passed?"PASS":"FAIL");else puts("Could not save result.");}
void weakAnalysis(void){char id[MAX_ID_LENGTH];int sem;if(!line("Student ID: ",id,sizeof id)||!integer("Semester: ",&sem))return;float t=weakThreshold();FILE*f=fopen(MARKS_FILE,"rb");MarkRecord m;Subject s;int n=0;if(!f){puts("No marks.");return;}printf("Weak threshold: %.2f%%\n",t);while(fread(&m,sizeof m,1,f)==1)if(!strcmp(m.studentId,id)&&m.semester==sem&&findSubject(m.subjectCode,&s)){float p=percentage(m.marksObtained,s.maximumMarks);if(p<t||m.marksObtained<s.passingMarks){printf("%s: %.2f%% (%s)\n",s.subjectName,p,m.marksObtained<s.passingMarks?"below pass requirement":"below improvement threshold");n++;}}fclose(f);if(!n)puts("No weak subjects detected.");}
void rankingMenu(void){int sem;if(!integer("Semester: ",&sem))return;RankingRecord a[MAX_STUDENTS];int n=buildRanking(sem,a,MAX_STUDENTS);if(!n){puts("No results.");return;}puts("RANK  ID        NAME                         %      STATUS");for(int i=0;i<n;i++)printf("%-5d %-9s %-28s %6.2f %s\n",a[i].rank,a[i].studentId,a[i].studentName,a[i].percentage,a[i].passed?"PASS":"FAIL");}
void analyticsMenu(void){int sem;if(!integer("Semester: ",&sem))return;FILE*f=fopen(RESULT_FILE,"rb");SemesterResult r;int n=0,pass=0;float sum=0,hi=-1,lo=101;if(f){while(fread(&r,sizeof r,1,f)==1)if(r.semester==sem){n++;sum+=r.percentage;if(r.passed)pass++;if(r.percentage>hi)hi=r.percentage;if(r.percentage<lo)lo=r.percentage;}fclose(f);}if(!n){puts("No results.");return;}printf("Students: %d | Average: %.2f%% | Highest: %.2f%% | Lowest: %.2f%% | Pass: %.2f%% | Fail: %.2f%%\n",n,sum/n,hi,lo,100.0f*pass/n,100.0f*(n-pass)/n);}
void compareSemesters(void){char id[MAX_ID_LENGTH];int a,b;SemesterResult x,y;if(!line("Student ID: ",id,sizeof id)||!integer("Previous semester: ",&a)||!integer("Current semester: ",&b)||a==b||!findResult(id,a,&x)||!findResult(id,b,&y)){puts("Comparison unavailable.");return;}float d=y.percentage-x.percentage;printf("Semester %d: %.2f%% | Semester %d: %.2f%% | Change: %+.2f percentage points | %s\n",a,x.percentage,b,y.percentage,d,d>0.001?"IMPROVED":d<-0.001?"DECLINED":"UNCHANGED");}
void generateReport(void){char id[MAX_ID_LENGTH];int sem;Student st;SemesterResult r;if(!line("Student ID: ",id,sizeof id)||!integer("Semester: ",&sem)||!findStudentById(id,&st)||!findResult(id,sem,&r)){puts("Finalized result not found.");return;}char path[160];snprintf(path,sizeof path,"reports/%s_Semester_%d.txt",id,sem);FILE*out=fopen(path,"w");if(!out){puts("Cannot create report.");return;}fprintf(out,"STUDENT ACADEMIC PERFORMANCE REPORT\n===================================\nStudent ID: %s\nRoll: %s\nName: %s\nBranch: %s\nSemester: %d\n\nSUBJECT PERFORMANCE\n",st.studentId,st.rollNumber,st.name,st.branch,sem);FILE*f=fopen(MARKS_FILE,"rb");MarkRecord m;Subject s;float t=weakThreshold();int weak=0;if(f){while(fread(&m,sizeof m,1,f)==1)if(!strcmp(m.studentId,id)&&m.semester==sem&&findSubject(m.subjectCode,&s)){float p=percentage(m.marksObtained,s.maximumMarks);char g[MAX_GRADE_LENGTH];getGrade(p,g);fprintf(out,"%-10s %-25s %6.2f/%6.2f %6.2f%% %s\n",s.subjectCode,s.subjectName,m.marksObtained,s.maximumMarks,p,g);if(p<t||m.marksObtained<s.passingMarks)weak++;}fclose(f);}int total=0,rank=getRank(id,sem,&total);fprintf(out,"\nOVERALL\nTotal: %.2f/%.2f\nPercentage: %.2f%%\nGrade: %s\nStatus: %s\nRank: %d/%d\nWeak subjects: %d\n",r.totalMarksObtained,r.totalMaximumMarks,r.percentage,r.overallGrade,r.passed?"PASS":"FAIL",rank,total,weak);if(sem>1){SemesterResult p;if(findResult(id,sem-1,&p)){float d=r.percentage-p.percentage;fprintf(out,"Trend from semester %d: %+.2f percentage points (%s)\n",sem-1,d,d>0.001?"IMPROVED":d<-0.001?"DECLINED":"UNCHANGED");}}fclose(out);printf("Report saved: %s\n",path);}
static int countFile(const char*path,size_t sz){FILE*f=fopen(path,"rb");if(!f)return 0;fseek(f,0,SEEK_END);long n=ftell(f);fclose(f);return n<0?0:(int)(n/(long)sz);}
void dashboard(void){printf("\nACADEMIC DASHBOARD\nStudents: %d\nSubjects: %d\nResults: %d\nWeak threshold: %.2f%%\n",countFile(STUDENT_FILE,sizeof(Student)),countFile(SUBJECT_FILE,sizeof(Subject)),countFile(RESULT_FILE,sizeof(SemesterResult)),weakThreshold());}
void settingsMenu(void){puts("Settings: default admin=admin / admin123. Grade and weak-threshold configuration files are initialized. Interactive editing will be finalized after runtime QA.");}
void mainMenu(void){for(;;){int c;if(!integer("\n=== STUDENT RESULT & GRADE ANALYZER ===\n1 Students\n2 Subjects\n3 Marks\n4 Calculate Result\n5 Weak Analysis\n6 Ranking\n7 Analytics\n8 Semester Comparison\n9 Generate Report\n10 Dashboard\n11 Settings\n12 Logout\nChoice: ",&c))continue;switch(c){case 1:studentMenu();break;case 2:subjectMenu();break;case 3:marksMenu();break;case 4:calculateResult();break;case 5:weakAnalysis();break;case 6:rankingMenu();break;case 7:analyticsMenu();break;case 8:compareSemesters();break;case 9:generateReport();break;case 10:dashboard();break;case 11:settingsMenu();break;case 12:return;default:puts("Invalid choice.");}}}
